/**
 * Oil & gas pipelines — real geometry from OpenStreetMap.
 *
 * Two layers, both © OpenStreetMap contributors (ODbL):
 *  1. World view: a static snapshot of every OSM `route=pipeline` relation
 *     tagged substance=oil|gas (the long-distance backbone), generated by
 *     `node scripts/build-pipelines.mjs` into public/data/pipelines-trunk.geojson.
 *  2. Detail view: when zoomed in, individual pipeline ways are pulled live in
 *     0.5° cells from the free/keyless Overpass API (no signup, no key, no
 *     billing account — same trust tier as the data-centre layer).
 *
 * This replaces the earlier hand-typed waypoint lists, which were approximate
 * and cut straight lines across terrain and borders.
 */

export type PipelineSubstance = 'oil' | 'gas'

/** Bright on purpose — the basemap is satellite imagery. */
export const PIPELINE_COLORS: Record<PipelineSubstance, string> = {
  oil: '#ff9a1f',
  gas: '#4fd1ff',
}

export const PIPELINE_LABELS: Record<PipelineSubstance, string> = {
  oil: 'Oil',
  gas: 'Gas',
}

export const PIPELINE_ATTRIBUTION = '© OpenStreetMap contributors (ODbL)'

/** Live per-way detail loads from this zoom; below it only the snapshot is drawn. */
export const PIPELINE_DETAIL_MIN_ZOOM = 9

const TRUNK_URL = `${import.meta.env.BASE_URL ?? '/'}data/pipelines-trunk.geojson`

const OVERPASS_ENDPOINTS = [
  'https://overpass-api.de/api/interpreter',
  'https://overpass.private.coffee/api/interpreter',
]

const CELL_DEG = 0.5
const MAX_CELLS_PER_VIEW = 30
const MAX_CACHED_CELLS = 120

export type PipelineFeature = GeoJSON.Feature<GeoJSON.LineString | GeoJSON.MultiLineString, PipelineProps>

export interface PipelineProps {
  osm: string
  name: string
  substance: PipelineSubstance
  color: string
  operator: string
  diameter: string
  location: string
}

const EMPTY: GeoJSON.FeatureCollection = { type: 'FeatureCollection', features: [] }

// ── Snapshot ──────────────────────────────────────────────────────────────────

let trunkCache: GeoJSON.FeatureCollection | null = null
let trunkInflight: Promise<GeoJSON.FeatureCollection> | null = null

function isSubstance(v: unknown): v is PipelineSubstance {
  return v === 'oil' || v === 'gas'
}

/** Load the world snapshot. Returns an empty collection (and retries next call) on any failure. */
export async function fetchTrunkPipelines(): Promise<GeoJSON.FeatureCollection> {
  if (trunkCache) return trunkCache
  if (trunkInflight) return trunkInflight
  trunkInflight = (async () => {
    try {
      const res = await fetch(TRUNK_URL)
      if (!res.ok) return EMPTY
      const json = await res.json() as GeoJSON.FeatureCollection
      if (!Array.isArray(json?.features)) return EMPTY
      const features: PipelineFeature[] = []
      for (const f of json.features) {
        const p = (f.properties ?? {}) as Record<string, unknown>
        const g = f.geometry
        if (!isSubstance(p.substance)) continue
        if (!g || (g.type !== 'LineString' && g.type !== 'MultiLineString')) continue
        features.push({
          type: 'Feature',
          geometry: g,
          properties: {
            osm: String(p.osm ?? ''),
            name: String(p.name ?? ''),
            substance: p.substance,
            color: PIPELINE_COLORS[p.substance],
            operator: String(p.operator ?? ''),
            diameter: '',
            location: '',
          },
        })
      }
      trunkCache = { type: 'FeatureCollection', features }
      return trunkCache
    } catch {
      return EMPTY
    } finally {
      trunkInflight = null
    }
  })()
  return trunkInflight
}

// ── Live detail cells ─────────────────────────────────────────────────────────

export interface PipelineCell {
  key: string
  south: number
  west: number
  north: number
  east: number
}

/** Grid cells covering a viewport, nearest the centre first, capped so a wide view can't fan out. */
export function cellsForBounds(west: number, south: number, east: number, north: number): PipelineCell[] {
  const clampLat = (v: number) => Math.max(-85, Math.min(85, v))
  const s = clampLat(south), n = clampLat(north)
  const cx = (west + east) / 2, cy = (s + n) / 2
  const cells: PipelineCell[] = []
  // Normalise longitudes so a view crossing the antimeridian still yields valid cells.
  const w = Math.max(-180, west), e = Math.min(180, east)
  for (let y = Math.floor(s / CELL_DEG); y * CELL_DEG < n; y++) {
    for (let x = Math.floor(w / CELL_DEG); x * CELL_DEG < e; x++) {
      cells.push({
        key: `${x}:${y}`,
        south: y * CELL_DEG, west: x * CELL_DEG,
        north: (y + 1) * CELL_DEG, east: (x + 1) * CELL_DEG,
      })
    }
  }
  const dist = (c: PipelineCell) => Math.hypot((c.west + c.east) / 2 - cx, (c.south + c.north) / 2 - cy)
  return cells.sort((a, b) => dist(a) - dist(b)).slice(0, MAX_CELLS_PER_VIEW)
}

interface OverpassWay {
  type: string
  id: number
  tags?: Record<string, string>
  geometry?: { lat: number; lon: number }[]
}

const r5 = (n: number) => Math.round(n * 1e5) / 1e5

/** Turn Overpass `out geom` ways into map features; ignores anything that isn't a drawable oil/gas line. */
export function wayToFeature(el: OverpassWay): PipelineFeature | null {
  if (el?.type !== 'way' || !Array.isArray(el.geometry) || el.geometry.length < 2) return null
  const t = el.tags ?? {}
  const substance = t.substance
  if (!isSubstance(substance)) return null
  const coordinates: [number, number][] = []
  for (const p of el.geometry) {
    if (typeof p?.lat !== 'number' || typeof p?.lon !== 'number') continue
    coordinates.push([r5(p.lon), r5(p.lat)])
  }
  if (coordinates.length < 2) return null
  return {
    type: 'Feature',
    id: el.id,
    geometry: { type: 'LineString', coordinates },
    properties: {
      osm: `way/${el.id}`,
      name: t['name:en'] ?? t.name ?? '',
      substance,
      color: PIPELINE_COLORS[substance],
      operator: t.operator ?? '',
      diameter: t.diameter ?? '',
      location: t.location ?? '',
    },
  }
}

const cellCache = new Map<string, PipelineFeature[]>()
const cellInflight = new Map<string, Promise<PipelineFeature[]>>()

async function queryCell(c: PipelineCell): Promise<PipelineFeature[]> {
  const bbox = `${c.south},${c.west},${c.north},${c.east}`
  const query = `[out:json][timeout:40];way["man_made"="pipeline"]["substance"~"^(oil|gas)$"](${bbox});out geom qt 8000;`
  let lastErr: unknown
  for (const endpoint of OVERPASS_ENDPOINTS) {
    try {
      const res = await fetch(endpoint, {
        method: 'POST',
        body: 'data=' + encodeURIComponent(query),
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        signal: AbortSignal.timeout(45_000),
      })
      if (!res.ok) throw new Error(`Overpass HTTP ${res.status}`)
      const json = await res.json() as { elements?: OverpassWay[] }
      const out: PipelineFeature[] = []
      for (const el of json.elements ?? []) {
        const f = wayToFeature(el)
        if (f) out.push(f)
      }
      return out
    } catch (err) {
      lastErr = err
    }
  }
  throw lastErr
}

/** Fetch one cell. Successes are cached; failures return [] and are retried on the next visit. */
export function fetchPipelineCell(c: PipelineCell): Promise<PipelineFeature[]> {
  const hit = cellCache.get(c.key)
  if (hit) {
    cellCache.delete(c.key); cellCache.set(c.key, hit) // refresh LRU position
    return Promise.resolve(hit)
  }
  const running = cellInflight.get(c.key)
  if (running) return running
  const p = queryCell(c)
    .then(features => {
      cellCache.set(c.key, features)
      if (cellCache.size > MAX_CACHED_CELLS) cellCache.delete(cellCache.keys().next().value as string)
      return features
    })
    .catch(() => [] as PipelineFeature[])
    .finally(() => { cellInflight.delete(c.key) })
  cellInflight.set(c.key, p)
  return p
}
